cd "${S4E_HOME:?REFUSE(2): S4E_HOME unset}/SCRIP" || exit 2; F=../harness/scripts/util_header_fanin.py; [ -f "$F" ] || { echo "REFUSE(2): $F is absent"; exit 2; }; out=$(python3 -I "$F" --root "$PWD" 2>/dev/null) || { echo "REFUSE(2): the fan-in instrument could not read this tree (build it first)"; exit 2; }; col() { printf '%s\n' "$out" | awk -F'\t' -v h="$2" -v c="$1" '$7==h{print $c}'; }; [ ! -e src/ir/IR.h ] || { echo "RED: IR.h still exists"; exit 1; }; [ ! -e src/planner/planner_head.h ] || { echo "RED: planner_head.h still exists"; exit 1; }; [ ! -e src/ir/bb_build.h ] || { echo "RED: bb_build.h still exists"; exit 1; }; for f in src/ir/ir_fwd.h src/ir/ir_node.h src/ir/ir_graph.h src/ir/ir_construct.h src/planner/zeta_plan.h src/planner/act_words.h src/planner/plan_facts.h; do [ -s $f ] || { echo "RED: $f missing"; exit 1; }; done; a=$(col 1 ir/ir_node.h); au=$(col 3 ir/ir_node.h); b=$(col 1 ir/ir_graph.h); bu=$(col 3 ir/ir_graph.h); [ -n "$a" ] && [ -n "$b" ] || { echo "REFUSE(2): the instrument lists no ir_node.h or ir_graph.h row"; exit 2; }; [ "$a" -le 60 ] && [ "$b" -le 50 ] && [ "$a" -le $((au + 4)) ] && [ "$b" -le $((bu + 4)) ] && echo "GREEN: ir_node.h reaches $a units (users $au, ceiling 60), ir_graph.h $b (users $bu, ceiling 50), each within R4 (fan-in at most users + 4); IR.h reached 220" || { echo "RED: ir_node.h reaches $a (users $au, ceiling 60), ir_graph.h $b (users $bu, ceiling 50); R4 is fan-in at most users + 4"; exit 1; }
